-- US MD/MBBS (4th Year) clinical case blocks - Geriatrics: Osteoporosis & fracture prevention - DEXA criteria, bisphosphonates, fall cascade - Part 1 (1-100)
BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'geri-osteoporosis' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic geri-osteoporosis not found.';
    END IF;

    DELETE FROM mcqs WHERE topic_id = v_topic_id;

END $$;
COMMIT;
